	/**
	 * Default Constructor
	 */
    public MatterService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new MatterEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(MatterRepository.class) );
		this.validator		= applicationContext.getBean(MatterValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Matter
	 */
		public Matter createMatter( CreateMatterCommand command ) {

		Matter entity = new Matter();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setMatterId( command.getMatterId() );
            entity.setMatterName( command.getMatterName() );
            entity.setLeadCounsel( command.getLeadCounsel() );
            entity.setMatterType( command.getMatterType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Matter {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateMatterCommand
	 * @return		Matter
	 */
	public Matter updateMatter( UpdateMatterCommand command ) {

		Matter entity = new Matter();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setMatterId( command.getMatterId() );
            entity.setMatterName( command.getMatterName() );
            entity.setLeadCounsel( command.getLeadCounsel() );
            entity.setLegalHolds( command.getLegalHolds() );
            entity.setOrganization( command.getOrganization() );
            entity.setDataBreaches( command.getDataBreaches() );
            entity.setContracts( command.getContracts() );
            entity.setMatterType( command.getMatterType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Matter {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteMatterCommand
	 */
	public void delete( DeleteMatterCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getMatterId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Matter {0} ", id );

	}

	/**
	 * Method to retrieve the Matter via MatterFetchOneSummary
	 * @param 	summary MatterFetchOneSummary
	 * @return 	MatterFetchOneResponse
	 */
	public Matter getMatter( MatterFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "MatterFetchOneSummary arg cannot be null" );

		Matter entity = null;
		UUID id = summary.getMatterId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Matter using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Matters
	 *
	 * @return 	List<Matter>
	 */
    public List<Matter> getAllMatter() {
		List<Matter> list = projector.findAll( new FindAllMatterQuery() );
		return list;
	}

	/**
	 * assign Organization on Matter
	 * @param		command AssignOrganizationToMatterCommand
	 */
	public void assignOrganization( AssignOrganizationToMatterCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getMatterId(), command.getAssignment());

	}

